<script setup lang="ts">
import {Head,Link,useForm} from '@inertiajs/vue3';
import {ref} from 'vue';
import AppLayout from '../../layouts/AppLayout.vue';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import {rupiah as money} from '../../composables/costing';
import {progress,type OpsProgram,type ExpenseRow,type Budget} from '../../types/operations';
const props=defineProps<{header:ExpenseRow & {bank?:string;no_rekening?:string;nama_rekening?:string;paid_date?:string;paid_keterangan?:string;approved_by?:number;approved_date?:string;alasan_tolak?:string};program:OpsProgram;kind:string;details:{id:number;item:string;qty:string;harga:string;total:string}[];files:{id:number;nama_file:string}[];budget:Budget;history:{action:string;description:string;created_date:string}[];canApprove:boolean;canCancel:boolean;canPay:boolean}>();
const action=ref(''), form=useForm({alasan_tolak:'',paid_date:'',paid_keterangan:'',bukti:[] as File[]});
const send=()=>form.post(`/pengajuan-biaya/${props.kind}/${props.header.id}/${action.value}`,{forceFormData:true,onSuccess:()=>action.value=''});
</script>
<template><Head :title="header.nomor"/><AppLayout title="Pengajuan Biaya"><div class="page-head"><h1>{{header.nomor}}</h1><Link :href="`/pengajuan-biaya/program/${program.id}?kategori=${header.tipe_biaya}`">Program {{program.nomor}}</Link></div><section class="panel stack"><h2>{{program.judul}}</h2><p>{{header.jenis==='kasbon'?'Kasbon':header.jenis==='direct_payment'?'Direct Payment':'Overbudget'}} · {{header.tipe_biaya}} · {{header.tanggal}} · Request By {{header.pengaju}}</p><p>{{header.deskripsi || header.alasan}}</p><p>Progres: {{kind==='overbudget'?header.status:progress[header.status]}}</p><ol v-if="kind==='pengajuan' && !['ditolak','batal'].includes(header.status)" aria-label="Progres pengajuan"><li v-for="s in ['menunggu','disetujui','paid']" :key="s" :aria-current="s===header.status?'step':undefined">{{progress[s]}}{{s===header.status?' (saat ini)':''}}</li></ol><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Harga</th><th>Total</th></tr></thead><tbody><tr v-for="d in details" :key="d.id"><td>{{d.item}}</td><td>{{d.qty}}</td><td>{{money(d.harga)}}</td><td>{{money(d.total)}}</td></tr></tbody></table></div><strong>Grand Total {{money(header.total)}}</strong><p>Budget kategori {{money(budget.budget)}} · Aktual {{money(budget.aktual)}} · Sisa {{money(budget.sisa)}}</p><p v-if="header.bank">Rekening: {{header.bank}} · {{header.no_rekening}} · {{header.nama_rekening}}</p><a v-for="f in files" :key="f.id" :href="`/documents/expense/${f.id}`">{{f.nama_file}}</a><p v-if="header.paid_date">Paid {{header.paid_date}} · {{header.paid_keterangan}}</p><p v-if="header.alasan_tolak">Alasan ditolak: {{header.alasan_tolak}}</p><p v-if="program.closed_date" class="notice">Program Closed; pengajuan existing ini tetap dapat diselesaikan.</p><div v-if="header.status==='menunggu'" class="form-actions"><button v-if="canApprove" @click="action='setujui';form.clearErrors()">Setujui</button><button v-if="canApprove" @click="action='tolak';form.clearErrors()">Tolak</button><button v-if="canCancel" @click="action='batal';form.clearErrors()">Batalkan</button></div><button v-if="header.status==='disetujui' && canPay" @click="action='paid';form.clearErrors()">Tandai Paid</button><h3>Riwayat status</h3><p v-for="h in history" :key="h.created_date+h.action">{{h.created_date}} · {{h.action}} · {{h.description}}</p></section><ConfirmDialog v-if="action" :title="action==='paid'?'Tandai Paid':action==='setujui'?'Setujui pengajuan':action==='tolak'?'Tolak pengajuan':'Batalkan pengajuan'" :busy="form.processing" @cancel="action=''" @confirm="send"><label v-if="action==='tolak'">Alasan penolakan wajib<textarea v-model="form.alasan_tolak" maxlength="2000" required/></label><template v-if="action==='paid'"><p>Pembayaran dilakukan di luar aplikasi. Paid bersifat final.</p><label>Tanggal bayar wajib<input v-model="form.paid_date" type="date" :min="header.tanggal" required/></label><label>Keterangan<textarea v-model="form.paid_keterangan" maxlength="150"/></label><label>Bukti transfer opsional, PDF/JPG/PNG maks. 5 MB<input type="file" accept=".pdf,.jpg,.jpeg,.png" multiple @change="form.bukti=Array.from(($event.target as HTMLInputElement).files || [])"/></label></template><p v-else>Proses seluruh pengajuan {{header.nomor}} senilai {{money(header.total)}}?</p><p v-for="e in form.errors" :key="e" class="error" role="alert">{{e}}</p></ConfirmDialog></AppLayout></template>
